  RAL,
  RAR,
  TCC,
  DAC,
  TCS,
  STC,
  DAA,
  KBP,
  DCL,
};

Opcode get_current_opcode(Machine_State &state) {
  auto opbyte1 = state.rom.at(state.pc.get());
  switch (opbyte1 >> 4) {
  case 0b0000:
    return Opcode::NOP;
  case 0b0001:
    return Opcode::JCN;
  case 0b0010:
    switch (opbyte1 & 1) {
    case 0b0:
      return Opcode::FIM;
    case 0b1:
      return Opcode::SRC;
    }
  case 0b0011:
    switch (opbyte1 & 1) {
    case 0b0:
      return Opcode::FIN;
    case 0b1:
      return Opcode::JIN;
    }
  case 0b0100:
    return Opcode::JUN;
  case 0b0101:
    return Opcode::JMS;
  case 0b0110:
    return Opcode::INC;
  case 0b0111:
    return Opcode::ISZ;
  case 0b1000:
    return Opcode::ADD;
  case 0b1001:
    return Opcode::SUB;
  case 0b1010:
    return Opcode::LD;
  case 0b1011:
    return Opcode::XCH;
  case 0b1100:
    return Opcode::BBL;
  case 0b1101:
    return Opcode::LDM;
  case 0b1110:
    switch (opbyte1 & 0xf) {
    case 0b0000:
      return Opcode::WRM;
    case 0b0001:
      return Opcode::WMP;
    case 0b0010:
      return Opcode::WRR;
    case 0b0011:
      return Opcode::WR0;
    case 0b0100:
      return Opcode::WR1;
    case 0b0101:
      return Opcode::WR2;
    case 0b0110:
      return Opcode::WR3;
    case 0b0111:
      return Opcode::SBM;
    case 0b1001:
      return Opcode::RDM;
    case 0b1010:
      return Opcode::RDR;
    case 0b1011:
      return Opcode::ADM;
    case 0b1100:
      return Opcode::RD0;
    case 0b1101:
      return Opcode::RD1;
    case 0b1110:
      return Opcode::RD2;
    case 0b1111:
      return Opcode::RD3;
    }
  case 0b1111:
    switch (opbyte1 & 0xf) {
    case 0b0000:
      return Opcode::CLB;
    case 0b0001:
      return Opcode::CLC;
    case 0b0010:
      return Opcode::IAC;
    case 0b0011:
      return Opcode::CMC;
    case 0b0100:
      return Opcode::CMA;
    case 0b0101:
      return Opcode::RAL;
    case 0b0110:
      return Opcode::RAR;
    case 0b0111:
      return Opcode::TCC;
    case 0b1000:
      return Opcode::DAC;
    case 0b1001:
      return Opcode::TCS;
    case 0b1010:
      return Opcode::STC;
    case 0b1011:
      return Opcode::DAA;
    case 0b1100:
      return Opcode::KBP;
    case 0b1101:
      return Opcode::DCL;
    }
  }

  std::cerr << "Failed to decode opcode!!" << std::endl;
  abort();
}

size_t get_opcode_size(const Opcode opcode) {
  const std::unordered_map<Opcode, size_t> opcodes{
      {Opcode::NOP, 1}, {Opcode::JCN, 2}, {Opcode::FIM, 2}, {Opcode::SRC, 1},
      {Opcode::FIN, 1}, {Opcode::JIN, 1}, {Opcode::JUN, 2}, {Opcode::JMS, 2},
      {Opcode::INC, 1}, {Opcode::ISZ, 2}, {Opcode::ADD, 1}, {Opcode::SUB, 1},
      {Opcode::LD, 1},  {Opcode::XCH, 1}, {Opcode::BBL, 1}, {Opcode::LDM, 1},
      {Opcode::WRM, 1}, {Opcode::WMP, 1}, {Opcode::WRR, 1}, {Opcode::WPM, 1},
      {Opcode::WR0, 1}, {Opcode::WR1, 1}, {Opcode::WR2, 1}, {Opcode::WR3, 1},
      {Opcode::SBM, 1}, {Opcode::RDM, 1}, {Opcode::RDR, 1}, {Opcode::ADM, 1},
      {Opcode::RD0, 1}, {Opcode::RD1, 1}, {Opcode::RD2, 1}, {Opcode::RD3, 1},
      {Opcode::CLB, 1}, {Opcode::CLC, 1}, {Opcode::IAC, 1}, {Opcode::CMC, 1},
      {Opcode::CMA, 1}, {Opcode::RAL, 1}, {Opcode::RAR, 1}, {Opcode::TCC, 1},
      {Opcode::DAC, 1}, {Opcode::TCS, 1}, {Opcode::STC, 1}, {Opcode::DAA, 1},
      {Opcode::KBP, 1}, {Opcode::DCL, 1}};
  return opcodes.at(opcode);
}

