#!/usr/bin/env python3

# ROM data from offset 0x600-0x650 that contains the encoded flag
ENCODED_DATA = bytes.fromhex(
    '61666c6636652e6e746c39051600000000'
    'c68196d9c9c7b4355f9795d73224a625'
    'a2e024a725a3e06132'
)

def rotate_left(byte, n):
    return ((byte << n) | (byte >> (8 - n))) & 0xff

def rotate_right(byte, n):
    return ((byte >> n) | (byte << (8 - n))) & 0xff

def decode_byte(byte, key_byte):
    # First XOR with key byte
    result = byte ^ key_byte

    # Handle MSB transformations
    if result & 0x80:
        result &= 0x7f

    # Handle special bytes
    if result == 0x14:
        result = ord('_')
    elif result == 0x15:
        result = rotate_left(result, 1)
    elif result == 0x17:
        result = rotate_right(result, 1)

    return result

def decode_flag():
    # We know the flag starts with "flag{gYBa%5:E"
    known = b"flag{gYBa%5:E"
    key = []
    decoded = bytearray()

    # First, extract key from known portion
    for i in range(min(5, len(known))):
        key.append(known[i] ^ ENCODED_DATA[i])

    # Decode using the 5-byte key pattern
    for i in range(len(ENCODED_DATA)):
        decoded_byte = decode_byte(ENCODED_DATA[i], key[i % 5])
        if i < len(known):
            # Verify against known portion
            if decoded_byte != known[i]:
                print(f"Warning: Mismatch at pos {i}: got {chr(decoded_byte)}, expected {chr(known[i])}")
        decoded.append(decoded_byte)

    # Find the closing brace
    for i in range(len(decoded)-1, -1, -1):
        if decoded[i] == ord('}'):
            return decoded[:i+1]

    return decoded

if __name__ == '__main__':
    try:
        flag = decode_flag()
        print(f"Decoded flag: {flag.decode()}")
    except Exception as e:
        print(f"Error: {e}")

        # Debug: print raw decoded bytes
        print("\nDebug - Raw bytes:")
        flag = decode_flag()
        print(' '.join(f'{b:02x}' for b in flag))

#!/usr/bin/env python3
from binascii import hexlify, unhexlify

# Known encoded data from ROM
ENCODED_DATA = bytes.fromhex(
    '61666c6636652e6e746c39051600000000'
    'c68196d9c9c7b4355f9795d73224a625'
    'a2e024a725a3e06132'
)

def decode_byte(byte, key_byte, pos):
    # Initial XOR with key
    result = byte ^ key_byte

    # Handle MSB transformations for values > 0x7F
    if result & 0x80:
        base = result & 0x7f
        # Apply lookup table transformation
        if base == 0x14:
            result = ord('_')
        elif base == 0x15:
            result = ord('-')
        elif base == 0x17:
            result = ord('}')
        else:
            result = base

    # Additional transformations based on position
    if result in [0x14, 0x15, 0x17]:
        if result == 0x14:
            result = ord('_')
        elif result == 0x15:
            result = ord('-')
        elif result == 0x17:
            result = ord('}')

    return result

def decode_flag():
    # Known flag prefix
    known = b"flag{gYBa%5:E"
    key = bytearray()
    decoded = bytearray()

    # Extract key from known portion using first 5 bytes
    for i in range(5):
        key.append(known[i] ^ ENCODED_DATA[i])

    # Decode each byte with position-aware transformations
    for i in range(len(ENCODED_DATA)):
        decoded_byte = decode_byte(ENCODED_DATA[i], key[i % 5], i)
        decoded.append(decoded_byte)

        # Verify against known portion
        if i < len(known) and decoded_byte != known[i]:
            print(f"Position {i}: Got {chr(decoded_byte)} (0x{decoded_byte:02x}), "
                  f"Expected {chr(known[i])} (0x{known[i]:02x})")

    # Find and trim at closing brace
    try:
        end_pos = decoded.index(ord('}'), len(known))
        return decoded[:end_pos + 1]
    except ValueError:
        return decoded

if __name__ == '__main__':
    flag = decode_flag()

    # Print both hex and ASCII representation
    print("\nDecoded flag bytes:", hexlify(flag).decode())
    try:
        print("Decoded flag:", flag.decode())
    except UnicodeDecodeError:
        print("Warning: Some bytes couldn't be decoded as ASCII")

#!/usr/bin/env python3
from binascii import hexlify

# Intel 4004 has 4-bit registers, so we need to consider 4-bit operations
def nibble_rotate_left(n):
    return ((n << 1) | (n >> 3)) & 0xF

def nibble_rotate_right(n):
    return ((n >> 1) | (n << 3)) & 0xF

class Intel4004Decoder:
    def __init__(self):
        self.encoded_data = bytes.fromhex(
            '61666c6636652e6e746c39051600000000'
            'c68196d9c9c7b4355f9795d73224a625'
            'a2e024a725a3e06132'
        )
        self.key = self._derive_key()

    def _derive_key(self):
        # Known start of flag
        known = b"flag{gYBa%5:E"
        key = bytearray()

        # Get initial key bytes
        for i in range(5):
            key_byte = known[i] ^ self.encoded_data[i]
            key.append(key_byte)

